test('other branches keep running while a node waits, and end does not finish the run early', () => {
  const workflow = {
    id: 'late-end', entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: ['finish', 'work'] },
      { id: 'finish', type: 'end', result: 'early' },
