    throw new Error(`${label}: nodeId must be a non-empty string naming an action node`);
  }
  const target = nodes.get(ref.nodeId);
  if (!target) {
    throw new Error(`${label}: nodeId "${ref.nodeId}" does not name a node in this workflow`);
